<script>document.addEventListener('DOMContentLoaded',()=>{const norm=v=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();document.querySelectorAll('.uppercase-form input:not([type=date]):not([type=time]):not([type=number]),.uppercase-form textarea').forEach(e=>e.addEventListener('input',()=>e.value=norm(e.value)));document.querySelectorAll('.select2-control:not(:disabled)').forEach(s=>{s.hidden=true;s.required=false;const w=document.createElement('div'),i=document.createElement('input'),o=document.createElement('div');w.className='select2-widget';i.className='select2-search';i.required=true;i.setCustomValidity(s.value?'':'Seleccione una opción de la lista.');i.placeholder=s.dataset.placeholder;i.value=s.value?s.options[s.selectedIndex].text:'';o.className='select2-options';const render=()=>{o.innerHTML='';const q=norm(i.value);[...s.options].filter(x=>!q||norm(x.text).includes(q)).forEach(x=>{const b=document.createElement('button');b.type='button';b.className='select2-option';b.textContent=x.text;b.onclick=()=>{s.value=x.value;i.value=x.value?x.text:'';i.setCustomValidity(s.value?'':'Seleccione una opción de la lista.');w.classList.remove('open')};o.appendChild(b)})};i.onfocus=()=>{i.select();render();w.classList.add('open')};i.oninput=()=>{i.value=norm(i.value);s.value='';i.setCustomValidity('Seleccione una opción de la lista.');render()};s.addEventListener('change',()=>{i.value=s.value?s.options[s.selectedIndex].text:'';i.setCustomValidity(s.value?'':'Seleccione una opción de la lista.');});w.append(i,o);s.after(w)});document.addEventListener('click',e=>document.querySelectorAll('.select2-widget.open').forEach(w=>{if(!w.contains(e.target))w.classList.remove('open')}))});</script>
<script>
document.addEventListener('DOMContentLoaded',()=>{
 const sampleType=document.querySelector('[name="sample_type_code"]');
 const sampleOther=document.querySelector('[name="sample_type_other"]');
 if(sampleType && sampleOther){
   const updateOther=()=>{sampleOther.required=false;};
   sampleType.addEventListener('change',updateOther);
   updateOther();
 }
 const dialog=document.getElementById('cytology-reports-dialog');
 document.getElementById('open-cytology-reports')?.addEventListener('click',()=>dialog.showModal());
 document.getElementById('close-cytology-reports')?.addEventListener('click',()=>dialog.close());
 dialog?.querySelectorAll('select[name="period"]').forEach(select=>{
   select.addEventListener('change',()=>{
     const month=select.form.querySelector('select[name="month"]');
     month.disabled=select.value==='annual';
     month.closest('label').hidden=month.disabled;
   });
 });
 dialog?.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});
});
</script>
